# 选项：h 悲观盈利折扣；nm 不建模原因；tier 覆盖评级；trig 重估触发；inv 失效条件
Q = {}
def add(code, moat, barrier, growth, space, risk, rl, **kw):
    Q[code] = dict(moat=moat, barrier=barrier, growth=growth, space=space, risk=risk, rl=rl, **kw)

